    /* 鍦ㄣ€屽彂琛ㄣ€嶆寜閽乏杈规敞鍏ャ€孉I 鐢熸垚銆?*/
    function aiEnsureButton() {
        try {
            /* 鎵俱€屽彂琛ㄣ€嶆椂鎸?*闈㈢Н鏈€灏忕殑閭ｄ釜**锛氬畠鎵嶆槸鐪熸鏄剧ず鐨勬寜閽紝
               澶栧眰瀹瑰櫒锛堝鐭╁舰锛変細鎶?AI 鎸夐挳鎸ゅ埌绂汇€屽彂琛ㄣ€嶅緢杩滅殑鍦版柟銆?*/
            var nodes = document.querySelectorAll('button, a, div[role="button"]');
            var best = null, bestArea = Infinity;
            for (var k = 0; k < nodes.length; k++) {
                var cand = nodes[k];
                var t = (cand.textContent || '').trim();
                if (t !== '鍙戣〃' && t !== '鍙戝竷' && t !== '鎻愪氦') continue;
                var rr = cand.getBoundingClientRect();
                if (!rr.width || !rr.height) continue;      /* 闅愯棌鐨勪笉绠?*/
                var area = rr.width * rr.height;
                if (area < bestArea) { bestArea = area; best = cand; }
            }
            if (!best) return;
            for (var i = 0; i < nodes.length; i++) {
                var b = nodes[i];
                if (b !== best) continue;
                if (b.__slAiHost) continue;
                if (b.closest('[data-sl-ai-btn]')) continue;
                b.__slAiHost = true;
                var btn = document.createElement('button');
                btn.type = 'button';
                btn.setAttribute('data-sl-ai-btn', '1');
                btn.textContent = 'AI 鐢熸垚';
                btn.className = b.className || '';
                btn.style.cssText = (b.getAttribute('style') || '') +
                    ';margin-right:8px;background:#4D6BFE;border-color:#4D6BFE;color:#fff';
                btn.addEventListener('click', function (e) {
                    e.preventDefault();
                    e.stopPropagation();
                    aiButtonRun(btn);
                });
                /* 鈽?缁濆涓嶈兘鎶娿€屽彂琛ㄣ€嶆尓鍑哄師瀹瑰櫒锛堝寘 wrap 浼氳Е鍙?Vue 鐨?patch 鍐茬獊锛?                   鏁翠釜缂栬緫鍣ㄧ粍浠朵細琚嵏杞斤紝鐢ㄦ埛灏便€岀紪杈戝櫒涓嶈浜嗐€嶏級銆?                   鎵€浠ュ彧鎻掓寜閽紝鍐嶇敤 margin-left:auto 鎶婂畠鎺ㄥ埌鍙充晶銆佺揣璐村彂琛ㄣ€?*/
                if (b.parentNode) {
                    btn.style.marginLeft = 'auto';
                    btn.style.marginRight = '8px';
                    btn.style.flex = '0 0 auto';
                    b.parentNode.insertBefore(btn, b);
                }
                return;
            }
        } catch (e) { /* 蹇界暐 */ }
    }

